VALUES ('doc-01-heuer-psychology-p5-1', 'doc-01-heuer-psychology', '', 5, 'Tis book was prepared primarily for the use of US Government ofcials, and the format, coverage, and content were designed to meet their spe - cifc requirements.', 'kb-doc-01-heuer-psychology-p5-1', 1, 27, '01-heuer-psychology', 'retrieved', '0795F1F527241A80F405BFFF24B3E1D65C269FB55A416648770CA5ED57ABFC43', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
