INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p5-2', 'doc-01-heuer-psychology', '', 5, 'Because this book is now out of print, this Portable Document File (PDF) is formatted for two-sided printing to facilitate desktop publishing. It may be used by US Government agencies to make copies for govern - ment purposes and by non-governmental organizations to make copies for educational purposes. Because this book may be subject to copyright restriction, copies may not be made for any commercial purpose.', 'kb-doc-01-heuer-psychology-p5-2', 1, 66, '01-heuer-psychology', 'retrieved', 'B7DEB2B43E4C7AA35ECAF4AF7FC612B6AC135527E1CCBF4BEF28DA306EAB7390', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p5-4', 'doc-01-heuer-psychology', '', 5, 'All statements of fact, opinion, or analysis expressed in the main text of this book are those of the author. Similarly, all such statements in the Forward and the Introduction are those of the respective authors of those sections. Such statements of fact, opinion, or analysis do not necessarily refect the ofcial positions or views of the Central Intelligence Agency or any other component of the US Intelligence Community. Nothing in the contents of this book should be con - strued as asserting or implying US Government endorsement of fac- tual statements or interpretations.', 'kb-doc-01-heuer-psychology-p5-4', 1, 94, '01-heuer-psychology', 'retrieved', '03341D3F6802EDC520AABAD0CD23B40A6022C44C9815290980341D9856F21FC0', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
