VALUES ('doc-01-heuer-psychology-p8-2', 'doc-01-heuer-psychology', '', 8, 'Chapter 11: Biases in Perception of Cause and Efect127 Chapter 12: Biases in Estimating Probabilities..........147 Chapter 13: Hindsight Biases in Evaluation of Intelligence Reporting...............................................161 PART IV—CONCLUSIONS .............................173 Chapter 14: Improving Intelligence Analysis.............173 vi', 'kb-doc-01-heuer-psychology-p8-2', 1, 33, '01-heuer-psychology', 'retrieved', '3A9A4A628938E4971056B398724022106FB544341A387FEE872D877AD0F6169D', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
