INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p29-2', 'doc-01-heuer-psychology', '', 29, 'A basic fnding of cognitive psychology is that people have no conscious experience of most of what happens in the human mind. Many functions as- sociated with perception, memory, and information processing are conducted prior to and independently of any conscious direction. What appears sponta- neously in consciousness is the result of thinking, not the process of thinking.', 'kb-doc-01-heuer-psychology-p29-2', 1, 58, '01-heuer-psychology', 'retrieved', 'D4212AD9A1C6963D7C17DBF6E542D5479B7F3DA2A53B83E6A7D5D08EF6D1A4FC', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p29-3', 'doc-01-heuer-psychology', '', 29, 'Weaknesses and biases inherent in human thinking processes can be demonstr ated through carefully designed experiments. Tey can be alleviated by conscious application of tools and techniques that should be in the analyti- cal tradecraft toolkit of all intelligence analysts.', 'kb-doc-01-heuer-psychology-p29-3', 1, 40, '01-heuer-psychology', 'retrieved', '6C72E6CAF5602BB21C1C273BC1B18263CC494459EA87C3DE07E9C36E03670FE1', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p29-4', 'doc-01-heuer-psychology', '', 29, '* * * * * * * * * * * * * * * * * * * “When we speak of improving the mind we are usually referring to the acquisition of information or knowledge, or to the type of thoughts one should have, and not to the actual functioning of the mind. We spend little time monitoring our own thinking and comparing it with a more sophisticated ideal.” 12 When we speak of improving intelligence analysis, we are usually referring to the quality of writing, types of analytical products, relations between intelligence analysts and intelligence consumers, or organization 12. James L. Adams, Conceptual Blockbusting: A Guide to Better Ideas (New York: W .W . Norton, second edition, 1980), p . 3.', 'kb-doc-01-heuer-psychology-p29-4', 1, 124, '01-heuer-psychology', 'retrieved', '6AC795E2BEA1105B88E3F91D7C22CC89B5511857A309ACB98719779905700008', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
