INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p30-1', 'doc-01-heuer-psychology', '', 30, 'of the analytical process. Little attention is devoted to improving how analysts think.', 'kb-doc-01-heuer-psychology-p30-1', 1, 13, '01-heuer-psychology', 'retrieved', 'D7CADF174DD1B66D2A78688256BED3FF784799DF0CCD6F14F35553E3A3880AFF', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
