INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p31-3', 'doc-01-heuer-psychology', '', 31, '16. Christopher Brady, “Intelligence Failures: Plus Ca Change. . .” Intelligence and National S ecurity, Vol. 8, No. 4 (October 1993). N. Cigar, “Iraq’s Strategic Mindset and the Gulf War: Blueprint for Defeat,” Te Journal of Strategic Studies, Vol. 15, No. 1 (March 1992). J. J.', 'kb-doc-01-heuer-psychology-p31-3', 1, 46, '01-heuer-psychology', 'retrieved', '4E649ADEEC6D3ED99581DB38BED21D84D936CB049D4FDB9DD32B6FF99ACAC212', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
