INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p31-4', 'doc-01-heuer-psychology', '', 31, 'Wirtz, Te T et Ofensive: Intelligence Failure in War (New York, 1991). Ephraim Kam, Surprise Attack (Harvard University Press, 1988). Richard Betts, Surprise Attack: Lessons for Defense Planning (Brookings, 1982). Abraham Ben-Zvi, “Te Study of Surprise Attacks,” British Journal of International Studies, Vol. 5 (1979). Iran: Evaluation of Intelligence Performance Prior to November 1978 (Staf Report, Subcommittee on Evaluation, Permanent Select Committee on Intelligence, US House of Representatives, January 1979). Richard Betts, “Analysis, War and Decision: Why Intelligence Failures Are Inevitable,” World Politics, Vol. 31, No. 1 (October 1978). Richard W . Shryock, “Te Intelligence Community Post-Mortem Program, 1973- 1975,” Studies in Intelligence, Vol. 21, No. 1 (Fall 1977). Avi Schlaim, “Failures in National I ntelligence Estimates: Te Case of the Yom Kippur War,” World Politics, Vol. 28 (April 1976).', 'kb-doc-01-heuer-psychology-p31-4', 1, 130, '01-heuer-psychology', 'retrieved', '68857FF35E4C3238D6DD606D2D6031AF96B7B5139836841F3F8BCF166AB29F94', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
