VALUES ('doc-01-heuer-psychology-p32-1', 'doc-01-heuer-psychology', '', 32, 'experiments in cognitive psychology rather than through examples from diplomatic and military history.', 'kb-doc-01-heuer-psychology-p32-1', 1, 13, '01-heuer-psychology', 'retrieved', '13CCF898FC52DA5AFE5C5FF314FB44AB4432E2E8042DF1AB6AC5586391758313', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
