INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p32-7', 'doc-01-heuer-psychology', '', 32, 'Not enough training is focused in this direction—that is, inward to ward the analyst’s own thought processes. T raining of intelligence ana- 4', 'kb-doc-01-heuer-psychology-p32-7', 1, 23, '01-heuer-psychology', 'retrieved', '34030781C4A4DB05DC241F7214DD1244DCA952150FE6D0698F87752D3B410002', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
