INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p33-1', 'doc-01-heuer-psychology', '', 33, 'lysts generally means instruction in organizational procedures, method - ological techniques, or substantive topics. More training time should be dev oted to the mental act of thinking or analyzing. It is simply assumed, incorrectly, that analysts know how to analyze. Tis book is intended to support training that examines the thinking and reasoning processes involved in intelligence analysis.', 'kb-doc-01-heuer-psychology-p33-1', 1, 58, '01-heuer-psychology', 'retrieved', '165DB86DF2B8B647EDBF912047A59C18A38D25E4CB53ACF484F05ED2ED6F49C3', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
