INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p40-3', 'doc-01-heuer-psychology', '', 40, '26. Tis picture was originally published in Puck magazine in 1915 as a cartoon entitled “My Wife and M y Mother-in-Law.” 12', 'kb-doc-01-heuer-psychology-p40-3', 1, 22, '01-heuer-psychology', 'retrieved', '31EAF884391136480B2B67EA003DF6F414FD4E947782BA107C7C548ED74797DB', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
