INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p54-1', 'doc-01-heuer-psychology', '', 54, 'names or words have been devised by various memory experts, but these require some study and practice in their use.', 'kb-doc-01-heuer-psychology-p54-1', 1, 20, '01-heuer-psychology', 'retrieved', '9CCC780A39EC898E152319F7978CA360FA05ED64A25FE18B74843E200E49A022', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
