INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p54-2', 'doc-01-heuer-psychology', '', 54, 'Mnemonic devices are useful for remembering information that does not ft any appropriate conceptual structure or schema already in memory. Tey work by providing a simple, artifcial structure to which the information to be learned is then linked. Te mnemonic device sup - plies the mental “fle categories” that ensure retrievability of information.', 'kb-doc-01-heuer-psychology-p54-2', 1, 53, '01-heuer-psychology', 'retrieved', '07D68CA133ABA4BEA72949F015C83B85111926BB94098CD9E309D1CB4B6EAAA0', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p54-3', 'doc-01-heuer-psychology', '', 54, 'T o remember, frst recall the mnemonic device, then access the desired information.', 'kb-doc-01-heuer-psychology-p54-3', 1, 13, '01-heuer-psychology', 'retrieved', '76B29308404BC1A91D5FDCA8BFC0C684DACD28AF52F4D51891B4DB43B8B9B0EF', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
