VALUES ('doc-01-heuer-psychology-p80-1', 'doc-01-heuer-psychology', '', 80, 'to the totality of material an analyst has available to work with in making a judgment.', 'kb-doc-01-heuer-psychology-p80-1', 1, 16, '01-heuer-psychology', 'retrieved', 'DA24EED94F04C630B85B791169577D38BAD731305D109950ECB4B3253ECB5D49', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
