INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p80-2', 'doc-01-heuer-psychology', '', 80, 'Key fndings from this research are: • Once an experienced analyst has the minimum information nec- essary to make an informed judgment, obtaining additional in - formation generally does not improve the accuracy of his or her estimates.', 'kb-doc-01-heuer-psychology-p80-2', 1, 38, '01-heuer-psychology', 'retrieved', 'C386ADD1F963281FE2A147710ACA77564C4805D825C4635EAD237F294BD5C63B', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
