INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p83-6', 'doc-01-heuer-psychology', '', 83, '57. Arthur S. Elstein et al., Medical Problem Solving: An Analysis of Clinical Reasoning (Cambridge, MA and London: Har vard University Press, 1978), pp. 270 and 295.', 'kb-doc-01-heuer-psychology-p83-6', 1, 27, '01-heuer-psychology', 'retrieved', 'EA63CA027DB7BDC958CB9DBA7061B9343BC6F935CA9DC9D84A4C7B850E151195', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
