INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p84-8', 'doc-01-heuer-psychology', '', 84, '60. For a list of references, see Paul Slovic and Sarah Lichtenstein, “Comparison of Bayesian and Regr ession Approaches to the Study of Information Processing in Judgment,” Organizational Behavior and Human Performance, 6 (1971), p. 684.', 'kb-doc-01-heuer-psychology-p84-8', 1, 36, '01-heuer-psychology', 'retrieved', '1DDD0A056C0E1A37C506968F40DD9FED12476547ED14FA706B629BD31F7D4B6C', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
