INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p85-2', 'doc-01-heuer-psychology', '', 85, 'prediction of future socioeconomic growth of underdeveloped nations.61 Te mathematical model based on the analyst’s actual decisions is invari- ably a more accurate description of that analyst’s decisionmaking than the analyst’ s own verbal description of how the judgments were made.', 'kb-doc-01-heuer-psychology-p85-2', 1, 41, '01-heuer-psychology', 'retrieved', '786DBA3FC7755DD2393264F9804246A5031EC6AE6921ADF66D56D6E5B456822A', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
