VALUES ('doc-01-heuer-psychology-p93-7', 'doc-01-heuer-psychology', '', 93, 'R oberta Wohlstetter, “Cuba and Pearl Harbor: Hindsight and Foresight,” Foreign Afairs, Vol.', 'kb-doc-01-heuer-psychology-p93-7', 1, 13, '01-heuer-psychology', 'retrieved', 'B0A5EDF35E4344CFAB6DF0439A7215881BC71DE0C9761ACE16ADADCB84135686', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
