INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p102-5', 'doc-01-heuer-psychology', '', 102, '75. Abraham Ben Zvi, “Hindsight and Foresight: A Conceptual Framework for the Analysis of Surprise A ttacks,” World Politics, April 1976.', 'kb-doc-01-heuer-psychology-p102-5', 1, 21, '01-heuer-psychology', 'retrieved', '081703939C273D734E9FA69C4DBD92EC10ED5E806407A52C583162AC0BF808AC', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
