VALUES ('doc-01-heuer-psychology-p144-10', 'doc-01-heuer-psychology', '', 144, '93. A. Paivio, Imagery and Verbal Processes (New York: Holt, Rinehart & Winston, 1971).', 'kb-doc-01-heuer-psychology-p144-10', 1, 14, '01-heuer-psychology', 'retrieved', '31FDD94C7C5618866F09A9245C187E4DE3046108148770406F18C8F55B6964FD', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
