INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p160-3', 'doc-01-heuer-psychology', '', 160, 'Tis bias has important consequences. Assuming that a foreign gov - ernment’s actions result from a logical and centrally directed plan leads an analyst to: • Have expectations regarding that governmentÍs actions that may not be fulflled if the behavior is actually the product of shifting or inconsistent values, bureaucratic bargaining, or sheer confu- sion and blunder.', 'kb-doc-01-heuer-psychology-p160-3', 1, 57, '01-heuer-psychology', 'retrieved', '55F71DFD412FA1CDCA6B2775B6F2E515A58C25C75CAB0A83D9F27D7F624276C7', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
