INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p160-4', 'doc-01-heuer-psychology', '', 160, '• Draw far-reaching but possibly unwarranted inferences from iso- lated statements or actions by government ofcials who may be acting on their o wn rather than on central direction.', 'kb-doc-01-heuer-psychology-p160-4', 1, 29, '01-heuer-psychology', 'retrieved', 'C71E5F5687351F0CEB315BB172C93CEA6B5D2B92077772AD1768280F1C28DC1B', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
