VALUES ('doc-01-heuer-psychology-p160-5', 'doc-01-heuer-psychology', '', 160, '• Overestimate the United States'' ability to infuence the other government''s actions.', 'kb-doc-01-heuer-psychology-p160-5', 1, 12, '01-heuer-psychology', 'retrieved', '4E82B53DF7AB8D9354C83931C5BB97948D3F4080ED89B641D205FD71EE969730', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
