INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p160-6', 'doc-01-heuer-psychology', '', 160, '• Perceive inconsistent policies as the result of duplicity and Machiavellian maneuvers, rather than as the product of weak leadership, vacillation, or bargaining among diverse bureaucratic or political interests.', 'kb-doc-01-heuer-psychology-p160-6', 1, 29, '01-heuer-psychology', 'retrieved', '7EB8EACC5F95A29CF2F8AEACCF4F48EF41CBE414DDFDD78EA71C2F3B5390B92C', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
