VALUES ('doc-01-heuer-psychology-p161-5', 'doc-01-heuer-psychology', '', 161, '115. David Hackett Fischer, Historian’s Fallacies (New York: Harper T orchbooks, 1970), p. 177.', 'kb-doc-01-heuer-psychology-p161-5', 1, 14, '01-heuer-psychology', 'retrieved', '380DA5A43A49AE517C1E78E848204C43BB58235DF566ADFDC6EBAD01C2F254D5', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
