VALUES ('doc-01-heuer-psychology-p161-7', 'doc-01-heuer-psychology', '', 161, '117. Richard E. Nisbett and Timothy DeC. Wilson, “T elling More Tan We Can Know: Verbal R eports on Mental Processes,” Psychological Review (May 1977), p. 252.', 'kb-doc-01-heuer-psychology-p161-7', 1, 27, '01-heuer-psychology', 'retrieved', '40E4A76D0D2FB7CAE4B0A5739F5E6E331B3C78ACA02D060E2DAE2C9198557BDF', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
