INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p172-5', 'doc-01-heuer-psychology', '', 172, 'H ow many cases are there with high stakes when deception was not used? Tat is a lot harder to think about and to fnd out about; researchers sel - dom devote much efort to documenting negative cases, when something did not occur. Fortunately, Whaley did make a rough estimate that both deception and surprise were absent in one-third to one-half of the cases of “grand strategy” during this period, which is the basis for putting the number 35 in the lower left cell of Figure 17.', 'kb-doc-01-heuer-psychology-p172-5', 1, 87, '01-heuer-psychology', 'retrieved', '42C0C0C83198828432063FF2C5A4A467C6F7A5E140C0401F105C6EF1D0443860', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p172-6', 'doc-01-heuer-psychology', '', 172, '130. Robert Axelrod, “Te Rational Timing of Surprise,” World Politics, XXXI (January 1979), pp . 228-246.', 'kb-doc-01-heuer-psychology-p172-6', 1, 16, '01-heuer-psychology', 'retrieved', 'DE672D58BBF2CBCF041B4D28B66A45998F85A0AC2D16D2E16341442EF577A023', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
