INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p194-1', 'doc-01-heuer-psychology', '', 194, 'would be comparable with the other two groups. Te correct answers were marked on the questionnaire, and the subjects were asked to re - spond to the questions as they would have responded had they not been told the answer. Tis tested their ability to recall accurately how much they had known before they learned the correct answer. Te situation is comparable to that of intelligence consumers who are asked to evaluate how much they learned from a report, and who can do this only by trying to recollect the extent of their knowledge before they read the report.', 'kb-doc-01-heuer-psychology-p194-1', 1, 99, '01-heuer-psychology', 'retrieved', '8A5CC26718CAC2B960F1F3C870970E6674A15EC0A81A3E32CD4CBE17D78616A4', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p194-3', 'doc-01-heuer-psychology', '', 194, 'Te group clearly overestimated what they had known originally and un- derestimated how much they learned from having been told the answer.', 'kb-doc-01-heuer-psychology-p194-3', 1, 22, '01-heuer-psychology', 'retrieved', '3D28E46D97EADD44D97D2AD510CF5B1A72D1F7A56E4DE0875B1BB3B150B9C5BD', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
