VALUES ('doc-01-heuer-psychology-p197-7', 'doc-01-heuer-psychology', '', 197, '154. Roberta Wohlstetter, Pearl Harbor: Warning and Decision (Stanford, CA: Stanford U niversity Press, 1962), p. 387. Cited by Fischhof.', 'kb-doc-01-heuer-psychology-p197-7', 1, 20, '01-heuer-psychology', 'retrieved', '7179676C78FC806E4D4BBD54F7AE66EEE396F70263C8B602B2D4520AB3908E00', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
