INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p198-1', 'doc-01-heuer-psychology', '', 198, 'My own imperfect efort to replicate one of these experiments using intelligence analysts also supports the validity of the previous fndings.', 'kb-doc-01-heuer-psychology-p198-1', 1, 21, '01-heuer-psychology', 'retrieved', '99264574C83F461E270239E793F102115A7F14454D899A3E3246FC75E1AB4EC2', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
