INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p198-2', 'doc-01-heuer-psychology', '', 198, 'T o test the assertion that intelligence analysts normally overestimate the accuracy of their past judgments, there are two necessary preconditions.', 'kb-doc-01-heuer-psychology-p198-2', 1, 21, '01-heuer-psychology', 'retrieved', 'A505E68C7F70F667F1ECFD50FB1E35BB2CAB753ED35E7892394E06B88E5D887E', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
